                    chart.LeftColumn = 5;
                    chart.RightColumn = 11;
                    chart.Name = "Student Sample Chart";
                    chart.ChartType = ExcelChartType.Cone_Clustered_3D;
                    chart.DataRange = sheet.Range["B2:C6"];

