By default  is set to HAlignment. Here for example, we set 
to HAlignment property.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Add textbox
            ITextBox textbox = worksheet.TextBoxes.AddTextBox(5, 5, 40, 100);

            //Set text
            textbox.Text = "Text";

            //Set alignment
            textbox.HAlignment = ExcelCommentHAlign.Left;

            //Save and dispose
            workbook.SaveAs("Shapes.xlsx");
            workbook.Close();
        }

