By default if the style is created using  method, then the style will be created based on the Normal style
which is the default style. If the created style is modified then  will be set to "true".

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Create style
            IStyle style = workbook.Styles.Add("CustomStyle");

            //Check style initialized or not
            Console.WriteLine(style.IsInitialized);

            //Set rich text
            IRichTextString richText = worksheet["C2"].RichText;

            //Set text
            richText.Text = "Sample";

            //Set font
            IFont font = style.Font;

            //Set color
            font.Color = ExcelKnownColors.Red;

            //Set rich text font
            richText.SetFont(0, 5, font);

            //Check style initialized or not
            Console.Write(style.IsInitialized);

            //Save and dispose
            workbook.SaveAs("CellFormats.xlsx");
            workbook.Close();
            Console.ReadKey();
        }
//Output will be
//False
//True

