        pivotTable.Fields[3].Axis = PivotAxisTypes.Column;
        IPivotField pivotField = pivotTable.Fields[1];

        //Sorts pivot field items in the given order
        pivotField.Sort(new string[5] { "Breto", "Marson", "Jack", "Andrew", "Sam" });

