            //Add data
            sheet.Range["A1"].Text = "Jan";
            sheet.Range["B1"].Text = "Feb";
            sheet.Range["C1"].Text = "Mar";
            sheet.Range["D1"].Text = "Apr";
            sheet.Range["E1"].Text = "May";
            sheet.Range["F1"].Text = "Jun";
