            //Set serie data format
            IChartSerieDataFormat format = chart.Series[0].DataPoints.DefaultDataPoint.DataFormat;

            //Check auto marker
            Console.Write(format.IsAutoMarker);

            //Save and Dispose
            workbook.SaveAs("Chart.xlsx");
            workbook.Close();
            Console.ReadKey();
