The  objects in the  property list sets rules that how the icons should be applied.
Default IconSet  has only three icons, so the list will have three objects of type 
by default. If we change it to an IconSet which has more icons like  then the list size increases to five.
Here for example, we access the default objects in the  property list and set , 
and  properties.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create a worksheet.        
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;            
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Load data to Apply Conditional Formatting.
            worksheet["A1"].Text = "IconSets";
            worksheet["A2"].Number = 105;
            worksheet["A3"].Number = 120;
            worksheet["A4"].Number = 300;
            worksheet["A5"].Number = 240;
            worksheet["A6"].Number = 350;
            worksheet["A7"].Number = 460;
            worksheet["A8"].Number = 170;
            worksheet["A9"].Number = 280;
            worksheet["A10"].Number = 190;
            worksheet["A11"].Number = 100;

            //Create instance of IConditonalFormat and IConditionalFormats.
            IConditionalFormats formats = worksheet["A2:A11"].ConditionalFormats;
            IConditionalFormat format = formats.AddCondition();

            //Set FormatType as IconSet.
            format.FormatType = ExcelCFType.IconSet;
            IIconSet iconSet = format.IconSet;

            //Set conditions for IconCriteria.
            iconSet.IconCriteria[1].Type = ConditionValueType.Percentile;
            iconSet.IconCriteria[1].Value = "20";
            iconSet.IconCriteria[1].Operator = ConditionalFormatOperator.GreaterThan;

            iconSet.IconCriteria[2].Type = ConditionValueType.Percentile;
            iconSet.IconCriteria[2].Value = "70";
            iconSet.IconCriteria[2].Operator = ConditionalFormatOperator.GreaterThan;

            //Save and Dispose.
            workbook.SaveAs("ConditionalFormats.xlsx");
            workbook.Close();
        }

By default  will be applied when IconSet is applied. The default  is .
From the name we can say  has 3 icons, So the values in the cells are set icons based on their percentage ranges 0 to 33, 33 to 67 and 67 to 100.
where 100 is the maximum value in the conditional formatting range.
Here for example, we load 10 values and apply conditional formatting of  as .
we set  to  property.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create a worksheet.        
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;            
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Load data to Apply Conditional Formatting.
            worksheet["A1"].Text = "IconSets";
            worksheet["A2"].Number = 105;
            worksheet["A3"].Number = 120;
            worksheet["A4"].Number = 300;
            worksheet["A5"].Number = 240;
            worksheet["A6"].Number = 350;
            worksheet["A7"].Number = 460;
            worksheet["A8"].Number = 170;
            worksheet["A9"].Number = 280;
            worksheet["A10"].Number = 190;
            worksheet["A11"].Number = 100;

            //Create instance of IConditonalFormat and IConditionalFormats.
            IConditionalFormats formats = worksheet["A2:A11"].ConditionalFormats;
            IConditionalFormat format = formats.AddCondition();

            //Set FormatType as IconSet.
            format.FormatType = ExcelCFType.IconSet;
            IIconSet iconSet = format.IconSet;

            //Set IconSet.
            iconSet.IconSet = ExcelIconSetType.ThreeFlags;

            //Save and Dispose.
            workbook.SaveAs("ConditionalFormats.xlsx");
            workbook.Close();
        }

To change the IconSet criteria to apply icons based on the percentile value of the value present in the cells, we can set 
property to "True". By default it is set to "False" and the conditions are applied based on percentage values instead of percentile.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create a worksheet.        
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;            
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Load data to Apply Conditional Formatting.
            worksheet["A1"].Text = "IconSets";
            worksheet["A2"].Number = 105;
            worksheet["A3"].Number = 120;
            worksheet["A4"].Number = 300;
            worksheet["A5"].Number = 240;
            worksheet["A6"].Number = 350;
            worksheet["A7"].Number = 460;
            worksheet["A8"].Number = 170;
            worksheet["A9"].Number = 280;
            worksheet["A10"].Number = 190;
            worksheet["A11"].Number = 100;

            //Create instance of IConditonalFormat and IConditionalFormats.
            IConditionalFormats formats = worksheet["A2:A11"].ConditionalFormats;
            IConditionalFormat format = formats.AddCondition();

            //Set FormatType as IconSet.
            format.FormatType = ExcelCFType.IconSet;
            IIconSet iconSet = format.IconSet;

            //Set PercentileValues.
            iconSet.PercentileValues = true;

            //Save and Dispose.
            workbook.SaveAs("ConditionalFormats.xlsx");
            workbook.Close();
        }

The icons in the IconSet will be applied in a predefined way (from lowest value to highest). This order of applying icons can be reversed setting
 property to "True". By default the ReverseOrder property is set to "False". Here for in our example, we set it

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create a worksheet.        
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;            
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Load data to Apply Conditional Formatting.
            worksheet["A1"].Text = "IconSets";
            worksheet["A2"].Number = 105;
            worksheet["A3"].Number = 120;
            worksheet["A4"].Number = 300;
            worksheet["A5"].Number = 240;
            worksheet["A6"].Number = 350;
            worksheet["A7"].Number = 460;
            worksheet["A8"].Number = 170;
            worksheet["A9"].Number = 280;
            worksheet["A10"].Number = 190;
            worksheet["A11"].Number = 100;

            //Create instance of IConditonalFormat and IConditionalFormats.
            IConditionalFormats formats = worksheet["A2:A11"].ConditionalFormats;
            IConditionalFormat format = formats.AddCondition();

            //Set FormatType as IconSet.
            format.FormatType = ExcelCFType.IconSet;
            IIconSet iconSet = format.IconSet;

            //Set Order of IconSets.
            iconSet.ReverseOrder = true;

            //Save and Dispose.
            workbook.SaveAs("ConditionalFormats.xlsx");
            workbook.Close();
        }

If IconSet is applied then the values in the cells will be shown along with an icon. The values can be made hidden by setting 
